//! Development test adapter shared by offline fixtures and the stdin probe.
//!
//! This invokes the crate's public APIs. Independent expected values are
//! generated by Python references and read from validation/oracle.tsv.

use regit_daycount::day_count::{self, CouponPeriod, DayCountContext};
use regit_daycount::{Date, DayCount};

#[path = "operations.rs"]
mod operations;

const BASES: [DayCount; 11] = [
    DayCount::Act360,
    DayCount::Act365F,
    DayCount::Act365L,
    DayCount::ActActIsda,
    DayCount::ActActIcma,
    DayCount::Nl365,
    DayCount::OneOne,
    DayCount::Thirty360BondBasis,
    DayCount::ThirtyE360,
    DayCount::ThirtyE360Isda,
    DayCount::Bus252,
];

// Exhaustive matches deliberately make an added public variant a compile error
// until its independent oracle mapping is supplied.
fn basis_name(basis: DayCount) -> &'static str {
    match basis {
        DayCount::Act360 => "act360",
        DayCount::Act365F => "act365f",
        DayCount::Act365L => "act365l",
        DayCount::ActActIsda => "actactisda",
        DayCount::ActActIcma => "actacticma",
        DayCount::Nl365 => "nl365",
        DayCount::OneOne => "oneone",
        DayCount::Thirty360BondBasis => "thirty360bond",
        DayCount::ThirtyE360 => "thirtye360",
        DayCount::ThirtyE360Isda => "thirtye360isda",
        DayCount::Bus252 => "bus252",
    }
}

pub fn date(value: &str) -> Date {
    let mut parts = value.split('-');
    Date::ymd(
        parts.next().unwrap().parse().unwrap(),
        parts.next().unwrap().parse().unwrap(),
        parts.next().unwrap().parse().unwrap(),
    )
    .unwrap()
}

pub fn supported(fields: &[&str]) -> bool {
    match fields[1] {
        "fraction" => true,
        "business" | "holiday" | "bus252" => cfg!(feature = "calendars"),
        "date_op" | "roll_op" | "calendar_op" => operations::supported(fields),
        unknown => panic!("Unknown oracle fixture kind {unknown}"),
    }
}

pub fn evaluate(fields: &[&str]) -> Result<f64, String> {
    if let Some(result) = operations::evaluate(fields) {
        return result;
    }
    let start = date(fields[3]);
    if matches!(fields[1], "business" | "holiday") {
        return business(start, fields[2], fields[1] == "holiday");
    }
    if fields[1] == "bus252" {
        return bus252(start, date(fields[4]));
    }
    let basis = BASES
        .into_iter()
        .find(|&basis| basis_name(basis) == fields[2])
        .ok_or_else(|| format!("Unknown basis {}", fields[2]))?;
    let coupon = if fields[5] == "-" {
        None
    } else {
        Some(CouponPeriod {
            start: date(fields[5]),
            end: date(fields[6]),
            frequency: fields[7].parse().unwrap(),
        })
    };
    let context = DayCountContext {
        coupon,
        end_is_maturity: match fields[8] {
            "0" => Some(false),
            "1" => Some(true),
            _ => None,
        },
    };
    day_count::try_fraction(start, date(fields[4]), basis, context)
        .map_err(|error| format!("{error:?}"))
}

#[cfg(feature = "calendars")]
fn business(date: Date, name: &str, holiday: bool) -> Result<f64, String> {
    use regit_daycount::Calendar;
    use regit_daycount::calendar::{self, CoveragePolicy};

    let calendar = match name {
        "target2" => Calendar::Target2,
        "usnyse" => Calendar::UnitedStatesNyse,
        "usfed" => Calendar::UnitedStatesFederalReserve,
        "uslegacy" => Calendar::UnitedStates,
        "uk" => Calendar::UnitedKingdom,
        "japan" => Calendar::Japan,
        "switzerland" => Calendar::Switzerland,
        "hongkong" => Calendar::HongKong,
        "singapore" => Calendar::Singapore,
        "luxembourg" => Calendar::Luxembourg,
        other => return Err(format!("Unknown calendar {other}")),
    };
    // Comparison with another implementation is separate from official
    // verification. Future snapshots must opt in to projection explicitly.
    let result = if holiday {
        calendar::try_is_holiday_with_policy(date, calendar, CoveragePolicy::AllowProjected)
    } else {
        calendar::try_is_business_day_with_policy(date, calendar, CoveragePolicy::AllowProjected)
    };
    let checked = result.map_err(|error| format!("{error:?}"))?;
    let raw = if holiday {
        calendar::is_holiday(date, calendar)
    } else {
        calendar::is_business_day(date, calendar)
    };
    if raw != checked {
        return Err(format!("Calendar raw={raw} checked={checked}"));
    }
    if let Some((first, last)) = calendar::coverage(calendar).verified_years {
        if (first..=last).contains(&date.year()) {
            let verified = if holiday {
                calendar::try_is_holiday(date, calendar)
            } else {
                calendar::try_is_business_day(date, calendar)
            }
            .map_err(|error| format!("{error:?}"))?;
            if verified != checked {
                return Err(format!("Calendar verified={verified} projected={checked}"));
            }
        }
    }
    // An exhaustive enum-to-name mapping also checks the public catalogue at
    // Rust compilation time, complementing the generator's source inventory.
    let mapped = match calendar {
        Calendar::Target2 => "target2",
        Calendar::Luxembourg => "luxembourg",
        Calendar::UnitedStates => "uslegacy",
        Calendar::UnitedStatesNyse => "usnyse",
        Calendar::UnitedStatesFederalReserve => "usfed",
        Calendar::UnitedKingdom => "uk",
        Calendar::Japan => "japan",
        Calendar::Switzerland => "switzerland",
        Calendar::HongKong => "hongkong",
        Calendar::Singapore => "singapore",
    };
    if mapped != name {
        return Err(format!("Calendar mapping mismatch {mapped} vs {name}"));
    }
    Ok(f64::from(u8::from(checked)))
}

#[cfg(not(feature = "calendars"))]
fn business(_date: Date, _name: &str, _holiday: bool) -> Result<f64, String> {
    Err("calendars feature is disabled".to_owned())
}

#[cfg(feature = "calendars")]
fn bus252(start: Date, end: Date) -> Result<f64, String> {
    use regit_daycount::calendar::{self, CoveragePolicy};
    let checked = calendar::try_bus_252_for_calendar_with_policy(
        start,
        end,
        regit_daycount::Calendar::Target2,
        CoveragePolicy::AllowProjected,
    )
    .map_err(|error| format!("{error:?}"))?;
    let raw = day_count::bus_252::fraction(start, end, |date| {
        calendar::is_business_day(date, regit_daycount::Calendar::Target2)
    });
    if (raw - checked).abs() > 1e-12 {
        return Err(format!("Bus/252 raw={raw:.17} checked={checked:.17}"));
    }
    Ok(checked)
}

#[cfg(not(feature = "calendars"))]
fn bus252(_start: Date, _end: Date) -> Result<f64, String> {
    Err("calendars feature is disabled".to_owned())
}
